(async () => {
  const post = (path) => fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: "{}" });
  await post("/api/auth/logout");
  await post("/api/local/session");
  const response = await fetch("/api/admin/overview", { credentials: "include" });
  const text = await response.text();
  return { status: response.status, text: text.slice(0, 300) };
})

(async () => {
  const credentials = { username: "acceptance_guest", password: "acceptance-password-12345" };
  const post = (path, body) => fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, credentials: "include", body: JSON.stringify(body) });
  await post("/api/auth/logout", {});
  await post("/api/local/session", {});
  let response = await post("/api/auth/register", credentials);
  if (response.status === 409) response = await post("/api/auth/login", credentials);
  const text = await response.text();
  return { status: response.status, text: text.slice(0, 400) };
})

